window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[48]={"id":"048","numero":48,"titre":"Alimentation chez l'enfant","objectifs":[{"id":"48-1","rang":"A","rubrique":"Prise en charge","titre":"Alimentation lactée exclusive : savoir avec quoi","contenu":"<p>L’<span class=\"kw-def\">alimentation lactée exclusive</span> couvre la totalité des besoins du nourrisson de la <strong>naissance à<span class=\"kw-chiffre\"> 4–6 mois</span></strong>. L’équipement enzymatique digestif <em>ne permet pas encore la digestion de l’amidon en grandes quantités</em> mais assure la digestion des protéines, lipides et glucides du lait. Trois options : <strong><span class=\"kw-ci\">allaitement</span> maternel</strong>, <strong>préparation lactée standard pour nourrissons</strong> ou <strong>préparation spécifique</strong>.</p>\n\n      <h4>Trois types d’alimentation lactée exclusive</h4>\n\n      <table >\n        <thead>\n          <tr><th>Option</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Allaitement</span> maternel</strong></td>\n            <td>\n              <ul>\n                <li>Référence — promotion indispensable (item 33)</li>\n                <li><span class=\"kw-alerte\">Supplémentation systématique en vitamine K</span> (<span class=\"kw-chiffre\">2 mg</span> PO à la naissance, J4–<span class=\"kw-chiffre\">J7</span>, M1 si AM exclusif)</li>\n                <li><span class=\"kw-alerte\">Supplémentation systématique en vitamine D</span> (<span class=\"kw-chiffre\">400–800 UI</span>/j, lait maternel très pauvre)</li>\n                <li>Supplémentation en <strong>fer</strong> à <span class=\"kw-chiffre\">M6</span> si AM exclusif (absorption à<span class=\"kw-chiffre\"> 50 %</span> seulement)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Préparation lactée standard pour nourrissons</strong></td>\n            <td>\n              <ul>\n                <li>Obtenue par transformation du lait de <strong>vache</strong> ou de <strong>chèvre</strong></li>\n                <li><span class=\"kw-ci\">N’a pas la fonction immunoprotectrice de l’AM</span> (la plupart des éléments immunologiques sont espèce-spécifiques)</li>\n                <li>Couvre <span class=\"kw-clinique\">les</span> besoins en <strong>fer</strong> (sels ferreux + vit. C → absorption <span class=\"kw-chiffre\">10–20 %</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Préparations spécifiques</strong></td>\n            <td>\n              <ul>\n                <li><strong>Anti-régurgitation</strong> (AR)</li>\n                <li><strong>Sans lactose</strong></li>\n                <li><strong>Hypoallergéniques</strong> (HA)</li>\n                <li><strong>Hydrolysats poussés de protéines</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-clinique\">Les</span> 3 préparations lactées standards selon l’âge</h4>\n\n      <table >\n        <thead>\n          <tr><th>Préparation</th><th>Âge</th><th>Rôle nutritionnel</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Préparation pour nourrissons (PN)</strong><br><em>1<sup>er</sup> âge</em></td>\n            <td><span class=\"kw-chiffre\">&lt; 4–6 mois</span></td>\n            <td>Répond <strong>à elle seule</strong> aux besoins nutritionnels jusqu’à la diversification</td>\n          </tr>\n          <tr>\n            <td><strong>Préparation de suite</strong><br><em>2<sup>e</sup> âge</em></td>\n            <td><span class=\"kw-chiffre\">4–6 mois → 1 an</span></td>\n            <td>Enrichissement en <strong>fer ++</strong> et <strong>AGE</strong> durant la diversification</td>\n          </tr>\n          <tr>\n            <td><strong>Préparation pour enfant en bas âge</strong><br><em>Lait de croissance</em></td>\n            <td><span class=\"kw-chiffre\">1–3 ans</span></td>\n            <td>Prévention des carences en <strong>fer +++</strong>, <strong>AGE</strong>, <strong>vit. D</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Lait de vache.</strong> <span class=\"kw-ci\">Formellement proscrit avant &lt; 1 an</span> ❌ :\n        <ul>\n          <li><strong>Trop riche</strong> en protéines, sodium</li>\n          <li><strong>Trop pauvre</strong> en acides gras essentiels, fer, <span class=\"kw-bio\">vitamine D</span></li>\n        </ul>\n      </div>\n\n      <h4>Préparations lactées spécifiques — indications</h4>\n\n      <table >\n        <thead>\n          <tr><th>Préparation</th><th>Principe / Indications</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Laits anti-régurgitation (AR)</strong></td>\n            <td>\n              <ul>\n                <li><strong>Objectif</strong> : augmenter la viscosité chez l’enfant avec <span class=\"kw-clinique\">régurgitations</span> isolées</li>\n                <li><strong>Comment</strong> : ajout d’<span class=\"kw-bio\">amidon</span> (maïs, tapioca, pomme de terre) ou de <span class=\"kw-bio\">farine de caroube</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Laits sans lactose</strong></td>\n            <td>\n              <ul>\n                <li>Lactose remplacé par <span class=\"kw-bio\">dextrine-maltose</span> ou polymères du glucose, parfois saccharose</li>\n                <li><strong>Indication</strong> : déficit en lactase (<span class=\"kw-ci\">intolérance</span> secondaire au lactose, rare : <span class=\"kw-chiffre\">&lt; 5 %</span>)</li>\n                <li>Au décours d’une <span class=\"kw-clinique\">diarrhée infectieuse sévère (rotavirus)</span> : lésions villositaires → déficit en lactase apicale → lactose non digéré → afflux d’eau → pérennisation de la <span class=\"kw-clinique\">diarrhée</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Hydrolysats extensifs de protéines</strong></td>\n            <td>\n              <ul>\n                <li><strong>Principe</strong> : hydrolysation <strong>extensive</strong> des protéines (lait de vache ou de <strong>riz</strong>) → diminution de l’allergénicité</li>\n                <li>Majoritairement <strong>dépourvus de lactose</strong> ; certains contiennent des <strong><span class=\"kw-bio\">triglycérides</span> à chaîne moyenne</strong> (absorption facilitée)</li>\n                <li><strong>Indication</strong> : <span class=\"kw-alerte\">allergie aux protéines du lait de vache (APLV)</span></li>\n                <li>Si inefficace → <strong>préparation à base d’acides aminés libres</strong> (anallergénique, dépourvue de peptides)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Laits hypoallergéniques (HA)</strong><br><em>ancien référentiel</em></td>\n            <td>\n              <ul>\n                <li>Hydrolysation <strong>partielle</strong> des protéines du lait de vache</li>\n                <li><span class=\"kw-ci\">Non indiqué dans le traitement de l’APLV</span> ❌</li>\n                <li>Place <strong>controversée</strong> en prévention chez <span class=\"kw-clinique\">les</span> nourrissons à risque d’<span class=\"kw-ci\">allergie</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 33 — <span class=\"kw-ci\">Allaitement</span> maternel · 32 — Évaluation du nouveau-né · 47 — <span class=\"kw-def\">Suivi</span> du nourrisson · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë</em></p>","frequence":5},{"id":"48-2","rang":"A","rubrique":"Prise en charge","titre":"Diversification de l’alimentation : savoir pourquoi","contenu":"<p>La <span class=\"kw-def\">diversification alimentaire</span> est la période de <strong>transition</strong> entre alimentation lactée exclusive et alimentation totalement diversifiée. Elle correspond à l’<strong>introduction progressive d’aliments autres que le lait</strong> entre <span class=\"kw-chiffre\">4 et 12 mois</span>. Son rationnel est triple : <strong>nutritionnel</strong>, <strong>immunologique</strong> et <strong>développemental</strong>.</p>\n\n      <h4><span class=\"kw-clinique\">Les</span> 3 raisons clés de la diversification</h4>\n\n      <table >\n        <thead>\n          <tr><th>Rationnel</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Couvrir <span class=\"kw-clinique\">les</span> besoins nutritionnels</strong></td>\n            <td>\n              <ul>\n                <li>Croissance et activité physique augmentent → besoins en <strong>fer</strong>, <strong>AGE</strong>, <strong>vitamines</strong> que le lait seul ne couvre plus à<span class=\"kw-chiffre\"> 6 mois</span></li>\n                <li>Apport calorique progressif via céréales, légumes, fruits, viande, poisson, œuf</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Acquisition de la tolérance immunologique</strong></td>\n            <td>\n              <ul>\n                <li>Introduction progressive des protéines alimentaires = <strong>essentielle pour prévenir <span class=\"kw-clinique\">les</span> manifestations allergiques</strong> ultérieures</li>\n                <li>Fenêtre de tolérance : <span class=\"kw-chiffre\">4–6 mois</span> (<strong>ni avant <span class=\"kw-chiffre\">4 mois</span>, ni après <span class=\"kw-chiffre\">6 mois</span></strong>)</li>\n                <li><span class=\"kw-clinique\">Gluten</span> à introduire entre <span class=\"kw-chiffre\">4 et 12 mois</span> en <strong>petites quantités progressivement croissantes</strong></li>\n                <li><span class=\"kw-clinique\">Arachide</span> (sous forme de beurre de cacahuète) à introduire entre <span class=\"kw-chiffre\">4 et 11 mois</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Maturation neuro-sensorielle et orale</strong></td>\n            <td>\n              <ul>\n                <li>Apprentissage de la <strong>cuillère</strong>, des <strong>textures</strong> et des <strong>saveurs</strong></li>\n                <li>Maturation des fonctions digestives, rénales, neurosensorielles</li>\n                <li>Prévention des <span class=\"kw-clinique\">troubles de l’oralité</span> (refus des morceaux)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Fenêtre temporelle : pourquoi <span class=\"kw-chiffre\">4–6 mois</span> ?</h4>\n\n      <table >\n        <thead>\n          <tr><th>Trop tôt (&lt;<span class=\"kw-chiffre\"> 4 mois</span>)</th><th>Trop tard (&gt;<span class=\"kw-chiffre\"> 6 mois</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Immaturité enzymatique</span> (amidon mal digéré)</li>\n                <li><span class=\"kw-alerte\">Immaturité rénale</span> (charge osmotique)</li>\n                <li>Risque accru d’<span class=\"kw-ci\">allergie</span></li>\n                <li>Risque <span class=\"kw-etio\">infectieux</span> (immaturité immunitaire intestinale)</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Fenêtre de tolérance immunologique <strong>dépassée</strong> → ↑ risque d’<span class=\"kw-ci\">allergie</span></li>\n                <li>Carences (fer +++, AGE)</li>\n                <li>Risque de <strong>troubles de l’oralité</strong> (refus des nouvelles textures et saveurs)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Diversification chez l’enfant à risque <span class=\"kw-etio\">allergique</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Recommandation</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition du risque</strong></td>\n            <td><span class=\"kw-def\">Terrain</span> <span class=\"kw-etio\">atopique</span> chez <strong><span class=\"kw-chiffre\">≥ 1</span> parent du 1<sup>er</sup> degré</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td><span class=\"kw-alerte\">Diversification identique à celle des enfants non allergiques</span> — en particulier introduction des aliments réputés allergisants</td>\n          </tr>\n          <tr>\n            <td><strong>Aliments réputés allergisants</strong></td>\n            <td>\n              <ul>\n                <li><strong>Œuf</strong></li>\n                <li><strong>Poisson</strong></li>\n                <li><strong>Arachide</strong> (beurre de cacahuète) entre <span class=\"kw-chiffre\">4–11 mois</span></li>\n                <li><strong>Fruits à coque</strong></li>\n                <li><strong><span class=\"kw-etio\">Gluten</span></strong> entre <span class=\"kw-chiffre\">4–12 mois</span>, par petites quantités progressivement croissantes</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Diversifier <strong>ni avant <span class=\"kw-chiffre\">4 mois</span>, ni après <span class=\"kw-chiffre\">6 mois</span></strong>. La diversification chez l’enfant à risque <span class=\"kw-etio\">allergique</span> <strong>n’est pas différée</strong> et inclut <span class=\"kw-clinique\">les</span> allergènes majeurs — c’est ainsi qu’on prévient l’<span class=\"kw-ci\">allergie</span>, pas en l’évitant.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> du nourrisson · 186 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë</em></p>","frequence":2},{"id":"48-3","rang":"A","rubrique":"Prise en charge","titre":"Alimentation lactée exclusive : savoir comment","contenu":"<p>Pratique de l’alimentation lactée : modalités de <strong>reconstitution</strong> et de <strong>conservation</strong> des biberons, <strong>quantités</strong> selon l’âge, et <strong>supplémentations vitaminiques systématiques</strong>.</p>\n\n      <h4>Modalités de reconstitution du biberon</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalité</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Dosage</strong></td>\n            <td><span class=\"kw-chiffre\">1 cuillère-mesure pour 30 mL</span> d’eau faiblement minéralisée ou eau du robinet</td>\n          </tr>\n          <tr>\n            <td><strong>Eau du robinet</strong></td>\n            <td>\n              <ul>\n                <li><strong>Laisser couler <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>5</span> min</span>utes</strong> avant utilisation</li>\n                <li>Eau <strong>froide</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ordre de préparation</strong></td>\n            <td>Eau <strong>versée en premier</strong> dans le biberon, <strong>puis la poudre</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Stérilisation</strong></td>\n            <td>\n              <ul>\n                <li>Non indispensable</li>\n                <li>Lavage au lave-vaisselle ou à la main suffisant</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Stockage au réfrigérateur</strong></td>\n            <td><span class=\"kw-alerte\">Ne pas conserver dans la porte</span> du réfrigérateur</td>\n          </tr>\n          <tr>\n            <td><strong>Température au moment du biberon</strong></td>\n            <td>\n              <ul>\n                <li>Peut être donné à <strong>température ambiante</strong></li>\n                <li>Si chauffage : consommation <span class=\"kw-chiffre\">&lt; 30 min</span></li>\n                <li><span class=\"kw-ci\">Éviter le micro-ondes</span> (risque de brûlure)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Schéma indicatif des biberons — 1<sup>er</sup> trimestre</h4>\n\n      <table >\n        <thead>\n          <tr><th>Période</th><th>Schéma type</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>re</sup> semaine</strong></td>\n            <td><span class=\"kw-chiffre\">6–7 × 10 mL</span> à <span class=\"kw-chiffre\">J1</span>, puis <strong>+<span class=\"kw-chiffre\"> 10 mL</span>/jour</strong> → 6–7 ×<span class=\"kw-chiffre\"> 70 mL</span> au <span class=\"kw-chiffre\">J7</span></td>\n          </tr>\n          <tr><td><strong>2<sup>e</sup> semaine</strong></td><td><span class=\"kw-chiffre\">6 × 80 mL/jour</span></td></tr>\n          <tr><td><strong>3<sup>e</sup> semaine</strong></td><td><span class=\"kw-chiffre\">6 × 90 mL/jour</span></td></tr>\n          <tr><td><strong>4<sup>e</sup> semaine</strong></td><td><span class=\"kw-chiffre\">6 × 100 mL/jour</span></td></tr>\n          <tr><td><strong>2<sup>e</sup> mois</strong></td><td><span class=\"kw-chiffre\">6 × 120 mL/jour</span></td></tr>\n          <tr><td><strong>3<sup>e</sup> mois</strong></td><td><span class=\"kw-chiffre\">5 × 150 mL/jour</span></td></tr>\n          <tr><td><strong>4<sup>e</sup> mois</strong></td><td><span class=\"kw-chiffre\">4 × 180 mL/jour</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>Apports hydriques conseillés selon l’âge</h4>\n\n      <table >\n        <thead>\n          <tr><th>Âge</th><th>Apports hydriques (mL/kg/jour)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Naissance</strong></td><td><span class=\"kw-chiffre\">150 mL/kg/j</span></td></tr>\n          <tr><td><strong>&lt;<span class=\"kw-chiffre\"> 6 mois</span></strong></td><td><span class=\"kw-chiffre\">120 mL/kg/j</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">6 mois</span> –<span class=\"kw-chiffre\"> 2 ans</span></strong></td><td><span class=\"kw-chiffre\">100 mL/kg/j</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">2 – 5 ans</span></strong></td><td><span class=\"kw-chiffre\">80 mL/kg/j</span></td></tr>\n          <tr><td><strong>&gt;<span class=\"kw-chiffre\"> 5 ans</span></strong></td><td><span class=\"kw-chiffre\">55 mL/kg/j</span></td></tr>\n        </tbody>\n      </table>\n\n      <p><em>Eau =<span class=\"kw-chiffre\"> 75 %</span> du PdC <span class=\"kw-clinique\">les</span> 1<sup>res</sup> semaines,<span class=\"kw-chiffre\"> 60 %</span> à<span class=\"kw-chiffre\"> 1 an</span>. Le nourrisson est très dépendant des apports hydriques (immaturité de la concentration-dilution des urines).</em></p>\n\n      <h4>Apports énergétiques conseillés (règle des 100-50-25)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Poids</th><th>Apports énergétiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">0 – 10 kg</span></strong></td><td><span class=\"kw-chiffre\">100 kcal/kg/j</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">10 – 20 kg</span></strong></td><td><span class=\"kw-chiffre\">1000 kcal/j + 50 kcal/kg/j</span> au-delà</td></tr>\n          <tr><td><strong>&gt;<span class=\"kw-chiffre\"> 20 kg</span></strong></td><td><span class=\"kw-chiffre\">1500 kcal/j + 25 kcal/kg/j</span> au-delà</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Apports énergétiques conseillés selon l’âge</h4>\n\n      <p><em>Besoins majorés en phase de <strong>croissance rapide</strong> : <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 premières années</span> (&lt;<span class=\"kw-chiffre\"> 2 ans</span>) et la <strong>puberté</strong>.</em></p>\n\n      <table >\n        <thead>\n          <tr><th>Âge</th><th>Apports énergétiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">M1</span> – M3</strong></td><td><span class=\"kw-chiffre\">450 kcal/j</span></td></tr>\n          <tr><td><strong>M4 – <span class=\"kw-chiffre\">M6</span></strong></td><td><span class=\"kw-chiffre\">600 kcal/j</span></td></tr>\n          <tr><td><strong>M7 – M9</strong></td><td><span class=\"kw-chiffre\">750 kcal/j</span></td></tr>\n          <tr><td><strong>M10 – <span class=\"kw-chiffre\">M12</span></strong></td><td><span class=\"kw-chiffre\">900 kcal/j</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">2 – 5 ans</span></strong></td><td><span class=\"kw-chiffre\">N ans = 1N00 kcal/j</span> (peu importe le sexe ; ex. <span class=\"kw-chiffre\">1300 kcal/j</span> à<span class=\"kw-chiffre\"> 3 ans</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">≥ 6 ans</span></strong></td><td><span class=\"kw-chiffre\">N ans = 1N00 kcal/j</span> <strong>+ 100 kcal/j si garçon</strong> (ex. <span class=\"kw-chiffre\">1900 kcal/j</span> garçon de <span class=\"kw-chiffre\">8 ans</span>, <span class=\"kw-chiffre\">2200 kcal/j</span> fille de <span class=\"kw-chiffre\">12 ans</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Apports en macronutriments conseillés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Macronutriment</th><th>Apports nutritionnels conseillés (ANC)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Protéines</strong></td>\n            <td>\n              <ul>\n                <li>Jusqu’à<span class=\"kw-chiffre\"> 2 ans</span> : <span class=\"kw-chiffre\">≥ 10 g/j</span></li>\n                <li>Après <span class=\"kw-chiffre\">2 ans</span> : <span class=\"kw-chiffre\">≥ 1 g/kg/j</span> (≈ <span class=\"kw-chiffre\">15 %</span> des apports énergétiques, porté à <span class=\"kw-chiffre\">20 %</span> si <span class=\"kw-alerte\">dénutrition</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Lipides</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-chiffre\">0 – 6 mois</span> : <span class=\"kw-chiffre\">50 %</span> des apports énergétiques totaux</li>\n                <li>Après <span class=\"kw-chiffre\">6 mois</span> : <strong>diminution progressive</strong>, mais apports restant notables</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Glucides</strong></td>\n            <td>Source principale durant <span class=\"kw-clinique\">les</span> 1<sup>ers</sup> mois d’alimentation lactée exclusive = <span class=\"kw-bio\">lactose</span> (<span class=\"kw-bio\">glucose + galactose</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Supplémentations vitaminiques systématiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Vitamine</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Vitamine K</strong></td>\n            <td>\n              <ul>\n                <li><strong>Rôle</strong> : synthèse des facteurs de coagulation, période néonatale</li>\n                <li><strong>ANC</strong> : 5–<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>10</span> µg/j</span> jusqu’à<span class=\"kw-chiffre\"> 2 ans</span></li>\n                <li><span class=\"kw-ttt\">2 mg PO à la naissance</span></li>\n                <li><span class=\"kw-ttt\">2 mg PO entre J4–J7</span></li>\n                <li><span class=\"kw-ttt\">2 mg PO à 1 mois</span> <strong>si AM exclusif</strong> (lait maternel pauvre en vit. K) ; optionnel si préparation lactée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td>\n              <ul>\n                <li><strong>Rôle</strong> : absorption intestinale du calcium, minéralisation osseuse</li>\n                <li>Lait maternel pauvre (<span class=\"kw-chiffre\">25–70 UI/L</span>) ; préparations enrichies mais insuffisamment</li>\n                <li><strong>Femme enceinte</strong> : dose unique 80 000–100 <span class=\"kw-chiffre\">000 UI</span> au début du 7<sup>e</sup> mois</li>\n                <li><strong><span class=\"kw-chiffre\">0–2 ans</span></strong> : <span class=\"kw-ttt\">400–800 UI/j</span>, allaité ou non</li>\n                <li><strong><span class=\"kw-chiffre\">2–18 ans</span></strong>, absence de FR :<span class=\"kw-chiffre\"> 400–800 UI</span>/j ou 50 <span class=\"kw-chiffre\">000 UI</span>/trimestre ou 80 000–100 <span class=\"kw-chiffre\">000 UI</span> en début et fin d’hiver</li>\n                <li><strong><span class=\"kw-chiffre\">2–18 ans</span></strong>, présence de FR :<span class=\"kw-chiffre\"> 800–1600 UI</span>/j ou 50 <span class=\"kw-chiffre\">000 UI</span>/6 sem. ou 80 000–100 <span class=\"kw-chiffre\">000 UI</span>/<span class=\"kw-chiffre\">3 mois</span></li>\n                <li><strong>FR</strong> : peau p<span class=\"kw-chiffre\">igm</span>entée, absence d’<span class=\"kw-etio\">exposition solaire</span>, <span class=\"kw-etio\">obésité</span>, végétalisme</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Fer</strong></td>\n            <td>\n              <ul>\n                <li><strong>ANC</strong> :<span class=\"kw-chiffre\"> 6–10 mg</span>/j jusqu’à<span class=\"kw-chiffre\"> 10 ans</span>,<span class=\"kw-chiffre\"> 13–16 mg</span>/j après <span class=\"kw-chiffre\">10 ans</span></li>\n                <li><strong>Absorption</strong> : héminique (viande, poisson, abats)<span class=\"kw-chiffre\"> 20–30 %</span> ; non héminique (lait, végétaux, œuf)<span class=\"kw-chiffre\"> 2–5 %</span></li>\n                <li>Laits infantiles couvrent <span class=\"kw-clinique\">les</span> besoins (sels ferreux + vit. C →<span class=\"kw-chiffre\"> 10–20 %</span>)</li>\n                <li><span class=\"kw-alerte\">AM exclusif : supplémentation systématique à partir de M6</span></li>\n                <li>Lait de vache <strong>très pauvre</strong> en fer (inadapté)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Calcium</strong></td>\n            <td>\n              <ul>\n                <li><strong>Rôle</strong> : minéralisation optimale du squelette</li>\n                <li><strong>ANC</strong> :<span class=\"kw-chiffre\"> 280–450 mg</span>/j (<span class=\"kw-chiffre\">0–3 ans</span>),<span class=\"kw-chiffre\"> 800 mg</span>/j (<span class=\"kw-chiffre\">4–10 ans</span>),<span class=\"kw-chiffre\"> 1150 mg</span>/j (<span class=\"kw-chiffre\">11–17 ans</span>)</li>\n                <li>Apports : <strong>lait et produits laitiers 3–4 ×/j</strong>, eaux minérales calciques</li>\n                <li>Végétaux ne sont pas une source potentielle (faible biodisponibilité)</li>\n                <li>Supplémentation si consommation &lt;<span class=\"kw-chiffre\"> 300 mg</span>/j</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Rachitisme carentiel — à savoir reconnaître</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td>Syndrome clinico-radiologique par <span class=\"kw-alerte\">déficit sévère en vitamine D et/ou calcium</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>Périodes de forte croissance (<strong>nourrisson</strong>, <strong>adolescence</strong>) ; FR : AM exclusif insuffisamment supplémenté, végétalisme, peau p<span class=\"kw-chiffre\">igm</span>entée, vêtements couvrants</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Retard statural constant</span></li>\n                <li>Fontanelles larges, cranio-tabès</li>\n                <li>Bourrelets métaphysaires (poignets, genoux, chevilles), chapelet costal</li>\n                <li><strong>Genu varum</strong> ou <strong>genu valgum</strong></li>\n                <li>Hypotonie, hyperlaxité l<span class=\"kw-chiffre\">iga</span>mentaire</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Radiologie</strong></td>\n            <td><span class=\"kw-imagerie\">RX poignet/genou</span> : élargissement métaphyses, <span class=\"kw-radio\">spicule latéral</span>, cupule en « <strong><span class=\"kw-radio\">toit de pagode</span></strong> », déminéralisation, contours flous</td>\n          </tr>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <ul>\n                <li><strong>25(OH)-vitamine D effondrée</strong></li>\n                <li><strong><span class=\"kw-bio\">PAL</span> très élevées</strong></li>\n                <li><span class=\"kw-bio\">Calcémie</span> et <span class=\"kw-bio\">phosphorémie</span> : normales puis ↓</li>\n                <li><span class=\"kw-bio\">PTH</span> ↑ (hyperparathyroïdie secondaire)</li>\n                <li>Souvent : anémie hypochrome microcytaire ferriprive</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>PEC</strong></td>\n            <td>\n              <ul>\n                <li>Apport de <strong>calcium + <span class=\"kw-bio\">vitamine D</span></strong></li>\n                <li>Si <strong>normocalcémie</strong> : vit. D 200 <span class=\"kw-chiffre\">000 UI</span> en dose de charge puis <span class=\"kw-chiffre\">2000–5000 UI</span>/j</li>\n                <li>Si <strong>hypocalcémie</strong> : corriger la <span class=\"kw-bio\">calcémie</span> <span class=\"kw-alerte\">avant</span> de supplémenter en <span class=\"kw-bio\">vitamine D</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pièges fréquents.</strong>\n        <ul>\n          <li><span class=\"kw-ci\">Lait de vache &lt; 1 an</span> = formellement <span class=\"kw-ci\">proscrit</span></li>\n          <li><span class=\"kw-ci\">Micro-ondes pour le biberon</span> = risque de brûlure (jamais)</li>\n          <li><span class=\"kw-ci\">Stockage dans la porte du réfrigérateur</span> = température instable</li>\n          <li><span class=\"kw-ci\">Stériliser les biberons</span> n’est <strong>plus indispensable</strong></li>\n          <li><span class=\"kw-alerte\">Carence en AGE</span> = anomalies du développement psychomoteur</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 33 — <span class=\"kw-ci\">Allaitement</span> maternel · 32 — Évaluation du nouveau-né · 47 — <span class=\"kw-def\">Suivi</span> du nourrisson · 250 — Dénutrition</em></p>","frequence":6},{"id":"48-4","rang":"A","rubrique":"Prise en charge","titre":"Diversification de l’alimentation : savoir comment","contenu":"<p>Pratique de la diversification : <strong>quand</strong>, <strong>quels aliments</strong>, dans <strong>quelles textures</strong>, en conservant <span class=\"kw-clinique\">les</span> <strong>biberons/tétées</strong> et en <strong>ajoutant des graisses</strong>. Au-delà de <span class=\"kw-chiffre\">1 an</span>, transition progressive vers l’alimentation totalement diversifiée — avec des interdits spécifiques selon l’âge.</p>\n\n      <h4>Modalités pratiques de la diversification</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Quand débuter ?</strong></td>\n            <td>Entre <span class=\"kw-chiffre\">4 et 6 mois</span>. <span class=\"kw-alerte\">Jamais avant 4 mois.</span></td>\n          </tr>\n          <tr>\n            <td><strong>Quels aliments ?</strong></td>\n            <td>\n              Pas de règle scientifique stricte pour la séquence. Aliments à introduire :\n              <ul>\n                <li><strong>Céréales infantiles</strong> (farine avec <span class=\"kw-etio\">gluten</span>)</li>\n                <li><strong>Légumes, fruits</strong></li>\n                <li><strong>Laitages</strong></li>\n                <li><strong>Viandes, poissons, œufs</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention de l’<span class=\"kw-ci\">allergie</span></strong></td>\n            <td>\n              <ul>\n                <li>Diversification chez l’enfant à risque <span class=\"kw-etio\">allergique</span> = <strong>identique</strong> à celle des autres</li>\n                <li><strong>Arachide</strong> (beurre de cacahuète) : entre <span class=\"kw-chiffre\">4–11 mois</span></li>\n                <li><strong><span class=\"kw-etio\">Gluten</span></strong> : entre <span class=\"kw-chiffre\">4–12 mois</span>, en <strong>petites quantités progressivement croissantes</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Séquence des textures</strong><br><em>(prévention des troubles de l’oralité)</em></td>\n            <td>\n              <ol>\n                <li>Alimentation <strong>mixée / lisse</strong> : <span class=\"kw-chiffre\">4–8 mois</span></li>\n                <li>Alimentation <strong>moulinée</strong> : <span class=\"kw-chiffre\">8–10 mois</span></li>\n                <li><strong>Petits morceaux</strong> de tailles progressivement croissantes : <span class=\"kw-chiffre\">&gt; 10 mois</span></li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Biberons / tétées</strong></td>\n            <td>\n              <ul>\n                <li><strong>Conserver <span class=\"kw-chiffre\">≥ 3</span> biberons/tétées/jour</strong> jusqu’à<span class=\"kw-chiffre\"> 1 an</span></li>\n                <li><span class=\"kw-chiffre\">700 mL/j</span> de préparation de suite = totalité des besoins en <strong>fer</strong> et <strong>AGE</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Ajout de graisses</strong></td>\n            <td>\n              Ajout <strong>systématique</strong> de matières grasses (beurre ou huiles végétales) dans tous <span class=\"kw-clinique\">les</span> plats salés — faits maison ou en petits pots\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Diversification menée par l’enfant (DME)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td>Proposer des aliments <strong>en morceaux</strong> dès que le nourrisson peut tenir assis (vers <span class=\"kw-chiffre\">6 mois</span>) ; il se nourrit seul avec <span class=\"kw-clinique\">les</span> doigts, <span class=\"kw-ci\">allaitement</span> / biberons de lait infantile poursuivis en parallèle</td>\n          </tr>\n          <tr>\n            <td><strong>Avantage</strong></td>\n            <td><span class=\"kw-clinique\">Moins de troubles de l’oralité</span> qu’avec la diversification à la cuillère</td>\n          </tr>\n          <tr>\n            <td><strong>Inconvénients</strong></td>\n            <td>\n              <ul>\n                <li>Risques de <span class=\"kw-alerte\">fausses routes</span></li>\n                <li>Risques de <span class=\"kw-alerte\">carences en lipides et fer</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conclusion</strong></td>\n            <td><em>Intérêt limité ; à proposer seulement si <span class=\"kw-clinique\">les</span> conditions sont réunies</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Alimentation totalement diversifiée (&gt;<span class=\"kw-chiffre\"> 12 mois</span>)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Âge</th><th>Aliments <span class=\"kw-ci\">à proscrire</span> (risque <span class=\"kw-etio\">infectieux</span>)</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 1 an</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ci\">Miel</span> (botulisme infantile)</li>\n                <li><span class=\"kw-ci\">Lait de vache</span></li>\n                <li>+ tous <span class=\"kw-clinique\">les</span> interdits &lt;<span class=\"kw-chiffre\"> 3 ans</span> et &lt;<span class=\"kw-chiffre\"> 5 ans</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ci\">Viande, poisson, coquillages crus</span></li>\n                <li><span class=\"kw-ci\">Œuf cru</span> ou préparations à base d’œuf cru</li>\n                <li>+ tous <span class=\"kw-clinique\">les</span> interdits &lt;<span class=\"kw-chiffre\"> 5 ans</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 5 ans</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ci\">Viande hachée mal cuite</span></li>\n                <li><span class=\"kw-ci\">Lait cru</span></li>\n                <li><span class=\"kw-ci\">Fromage au lait cru</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils selon l’âge</h4>\n\n      <table >\n        <thead>\n          <tr><th>Tranche d’âge</th><th>Recommandations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">1 – 3 ans</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-chiffre\">≥ 250 mL</span>/j</strong> de préparation lactée standard pour enfants en bas âge (<strong>lait de croissance</strong>)</li>\n                <li>Indispensable pour <span class=\"kw-clinique\">les</span> apports en <strong>fer</strong> et <strong>AGE</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td>\n              <ul>\n                <li>Recommandations alimentaires identiques à celles de l’adulte, <strong>sauf produits laitiers : 3 ×/jour</strong> (<span class=\"kw-bio\">vs</span> 2 ×/j chez l’adulte)</li>\n                <li><strong>Éviter</strong> : café, thé, sodas, boissons caféinées, édulcorants, boissons édulcorées</li>\n                <li><strong>Limiter</strong> : produits à base de soja (phytoestrogènes), chocolat (nickel)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Néophobie alimentaire (<span class=\"kw-chiffre\">2–10 ans</span>)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td>Phénomène <strong>physiologique</strong> — souvent à l’égard des saveurs amères (légumes)</td>\n          </tr>\n          <tr>\n            <td><strong>Conduite à tenir</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Ne pas faire l’objet d’un forcing</span></li>\n                <li>Habituer aux différents aliments <strong>avant <span class=\"kw-chiffre\">2 ans</span></strong> (légumes, fruits notamment)</li>\n                <li>Demander à l’enfant de <strong>goûter au moins une fois</strong> et représenter l’aliment ultérieurement à plusieurs reprises sous des formes variées</li>\n                <li>Impliquer l’enfant dans la préparation des plats</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong>\n        <ul>\n          <li>Diversification entre <strong>4 et <span class=\"kw-chiffre\">6 mois</span></strong>, jamais avant.</li>\n          <li>Conserver <strong><span class=\"kw-chiffre\">≥ 3</span> biberons/tétées/jour</strong> jusqu’à<span class=\"kw-chiffre\"> 1 an</span>, <strong><span class=\"kw-chiffre\">≥ 250 mL</span>/j de lait de croissance</strong> entre 1 et <span class=\"kw-chiffre\">3 ans</span>.</li>\n          <li>Textures : <strong>mixée → moulinée → morceaux</strong> selon le calendrier 4–8 / 8–10 / &gt;<span class=\"kw-chiffre\"> 10 mois</span>.</li>\n          <li>Pas de <strong>miel</strong> avant <span class=\"kw-chiffre\">1 an</span>, pas de <strong>viande hachée mal cuite / lait cru</strong> avant <span class=\"kw-chiffre\">5 ans</span>.</li>\n          <li>Ajout systématique de <strong>matières grasses</strong> dans <span class=\"kw-clinique\">les</span> plats salés.</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> du nourrisson · 55 — Développement psychomoteur · 186 — <span class=\"kw-ci\">Hypersensibilité</span> et allergies · 286 — <span class=\"kw-clinique\">Diarrhée</span> aiguë</em></p>","frequence":4}],"astuces":[{"type":"info","titre":"Astuces & pièges et stratégie","contenu":"<p>Couches « Astuces de PU & Pièges » et « Stratégie & CAT » : à compléter après revue clinique.</p>"}],"strategie":{"redflags":"<ul><li><span class=\"kw-ci\">Lait de vache</span> <span class=\"kw-alerte\">formellement proscrit avant 1 an</span> : trop riche en <span class=\"kw-bio\">protéines</span> et <span class=\"kw-bio\">sodium</span>, trop pauvre en <span class=\"kw-bio\">AGE</span>, <span class=\"kw-bio\">fer</span> et <span class=\"kw-bio\">vitamine D</span></li><li><span class=\"kw-ci\">Miel</span> avant <span class=\"kw-chiffre\">1 an</span> → <span class=\"kw-alerte\">botulisme infantile</span></li><li>Avant <span class=\"kw-chiffre\">3 ans</span> : <span class=\"kw-ci\">viande, poisson, coquillages crus</span> et <span class=\"kw-ci\">œuf cru</span> proscrits (risque <span class=\"kw-etio\">infectieux</span>)</li><li>Avant <span class=\"kw-chiffre\">5 ans</span> : <span class=\"kw-ci\">viande hachée mal cuite</span>, <span class=\"kw-ci\">lait cru</span>, <span class=\"kw-ci\">fromage au lait cru</span> proscrits</li><li><span class=\"kw-def\">Rachitisme carentiel</span> : <span class=\"kw-clinique\">retard statural constant</span> + <span class=\"kw-clinique\">genu varum/valgum</span> + <span class=\"kw-clinique\">bourrelets métaphysaires</span> → <span class=\"kw-alerte\">déficit sévère en vitamine D et/ou calcium</span></li><li><span class=\"kw-alerte\">Carence en AGE</span> (acides gras essentiels) → <span class=\"kw-clinique\">anomalies du développement psychomoteur</span></li><li><span class=\"kw-def\">DME</span> (diversification menée par l'enfant) : risque de <span class=\"kw-alerte\">fausses routes</span> et de <span class=\"kw-alerte\">carences en lipides et fer</span></li><li><span class=\"kw-ci\">Micro-ondes</span> pour réchauffer le biberon → <span class=\"kw-alerte\">risque de brûlure</span></li></ul>","principes":"<p><span class=\"kw-def\">Alimentation lactée exclusive</span> de la naissance à <span class=\"kw-chiffre\">4–6 mois</span> (idéalement <span class=\"kw-ttt\">allaitement maternel</span>), puis <span class=\"kw-def\">diversification</span> progressive entre <span class=\"kw-chiffre\">4 et 6 mois</span>. <strong>Supplémentation en <span class=\"kw-ttt\">vitamine D</span> systématique</strong> quel que soit le mode d'alimentation.</p><p><strong>Alimentation lactée exclusive <span class=\"q\">— naissance à<span class=\"kw-chiffre\"> 4–6 mois</span></span></strong></p><p>Stérilisation des biberons <strong>non indispensable</strong> ; <span class=\"kw-ci\">ne pas conserver dans la porte du réfrigérateur</span>, <span class=\"kw-ci\">éviter le micro-ondes</span></p><ul><li><span class=\"kw-ttt\">Allaitement maternel</span> = référence (promotion indispensable)</li><li>Sinon <span class=\"kw-ttt\">préparation pour nourrissons</span> (1<sup>er</sup> âge) : couvre seule <span class=\"kw-clinique\">les</span> besoins jusqu'à la diversification</li><li>Reconstitution : <span class=\"kw-chiffre\">1 cuillère-mesure pour 30 mL</span> d'eau faiblement minéralisée, eau versée <strong>avant</strong> la poudre</li><li>Eau du robinet : laisser couler <span class=\"kw-chiffre\">5 min</span>, eau froide ; biberon chauffé consommé en <span class=\"kw-chiffre\">&lt; 30 min</span></li></ul><p><strong>Supplémentations vitaminiques systématiques</strong></p><p><span class=\"kw-ttt\">Vitamine D</span> systématique quel que soit le mode d'alimentation</p><ul><li><span class=\"kw-ttt\">Vitamine K</span> : <span class=\"kw-ttt\">2 mg PO</span> à la naissance, entre <span class=\"kw-chiffre\">J4–J7</span>, puis à <span class=\"kw-chiffre\">M1</span> si <span class=\"kw-ttt\">allaitement maternel exclusif</span></li><li><span class=\"kw-ttt\">Vitamine D</span> : <span class=\"kw-ttt\">400–800 UI/j</span> de <span class=\"kw-chiffre\">0 à 2 ans</span>, allaité ou non</li><li><span class=\"kw-ttt\">Fer</span> : supplémentation à partir de <span class=\"kw-chiffre\">M6</span> si <span class=\"kw-ttt\">allaitement maternel exclusif</span></li></ul><p><strong>Diversification <span class=\"q\">—<span class=\"kw-chiffre\"> 4–6 mois</span> à<span class=\"kw-chiffre\"> 12 mois</span></span></strong></p><p>Ajout <strong>systématique</strong> de <span class=\"kw-ttt\">matières grasses</span> (beurre, huiles végétales) dans tous <span class=\"kw-clinique\">les</span> plats salés</p><ul><li>Débuter entre <span class=\"kw-chiffre\">4 et 6 mois</span> — <span class=\"kw-alerte\">jamais avant 4 mois</span></li><li>Introduire <span class=\"kw-clinique\">les</span> allergènes (<span class=\"kw-clinique\">arachide</span> <span class=\"kw-chiffre\">4–11 mois</span>, <span class=\"kw-clinique\">gluten</span> <span class=\"kw-chiffre\">4–12 mois</span> par petites quantités) <strong>même chez l'enfant à risque <span class=\"kw-etio\">allergique</span></strong></li><li>Textures : <span class=\"kw-chiffre\">mixée 4–8 mois</span> → <span class=\"kw-chiffre\">moulinée 8–10 mois</span> → <span class=\"kw-chiffre\">morceaux &gt; 10 mois</span></li><li>Conserver <span class=\"kw-chiffre\">≥ 3 biberons/tétées/j</span> jusqu'à<span class=\"kw-chiffre\"> 1 an</span> (<span class=\"kw-chiffre\">700 mL/j</span> de préparation de suite = besoins en <span class=\"kw-bio\">fer</span> et <span class=\"kw-bio\">AGE</span>)</li></ul><p><strong>Préparations lactées spécifiques <span class=\"q\">— selon la situation</span></strong></p><p><span class=\"kw-ci\">Lait HA non indiqué dans le traitement de l'APLV</span></p><ul><li><span class=\"kw-clinique\">Régurgitations</span> isolées → <span class=\"kw-ttt\">lait anti-régurgitation</span> (épaissi par <span class=\"kw-bio\">amidon</span> ou <span class=\"kw-bio\">farine de caroube</span>)</li><li><span class=\"kw-etio\">Déficit en lactase</span> (au décours d'une <span class=\"kw-clinique\">diarrhée</span> à <span class=\"kw-etio\">rotavirus</span>) → <span class=\"kw-ttt\">lait sans lactose</span></li><li><span class=\"kw-alerte\">APLV</span> → <span class=\"kw-ttt\">hydrolysat extensif de protéines</span> ; si inefficace → <span class=\"kw-ttt\">préparation à base d'acides aminés libres</span></li></ul><p><strong>Rachitisme carentiel <span class=\"q\">— traitement</span></strong></p><p>Si <strong>hypocalcémie</strong> : corriger la <span class=\"kw-bio\">calcémie</span> <span class=\"kw-alerte\">avant</span> de supplémenter en <span class=\"kw-bio\">vitamine D</span></p><ul><li>Apport de <span class=\"kw-ttt\">calcium</span> + <span class=\"kw-ttt\">vitamine D</span></li><li>Si <strong>normocalcémie</strong> : <span class=\"kw-ttt\">vitamine D 200 000 UI</span> en dose de charge puis <span class=\"kw-ttt\">2000–5000 UI/j</span></li></ul><p><strong>Après <span class=\"kw-chiffre\">1 an</span></strong></p><p><span class=\"kw-ci\">Éviter</span> café/thé/sodas/édulcorants ; <strong>limiter</strong> soja (phytoestrogènes) et chocolat (nickel)</p><ul><li><span class=\"kw-chiffre\">1–3 ans</span> : <span class=\"kw-ttt\">lait de croissance</span> <span class=\"kw-chiffre\">≥ 250 mL/j</span> (apports en <span class=\"kw-bio\">fer</span> et <span class=\"kw-bio\">AGE</span>)</li><li><span class=\"kw-chiffre\">&gt; 3 ans</span> : alimentation type adulte sauf <strong>produits laitiers 3×/j</strong> (<span class=\"kw-bio\">vs</span> 2×/j chez l'adulte)</li></ul>","suivi":"<p><strong>Croissance :</strong> besoins énergétiques majorés en phase de <strong>croissance rapide</strong> — <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">2 premières années</span> et la <span class=\"kw-clinique\">puberté</span> ; <span class=\"kw-ttt\">vitamine D</span> poursuivie, doses adaptées si FR (<span class=\"kw-etio\">peau pigmentée</span>, faible ensoleillement, <span class=\"kw-etio\">obésité</span>, <span class=\"kw-etio\">végétalisme</span>).</p><p><strong>Néophobie alimentaire <span class=\"q\">—<span class=\"kw-chiffre\"> 2 à 10 ans</span></span></strong></p><p><span class=\"kw-ci\">Ne pas faire l'objet d'un forcing</span></p><ul><li>Phénomène <span class=\"kw-def\">physiologique</span>, souvent envers <span class=\"kw-clinique\">les</span> saveurs amères (<span class=\"kw-clinique\">légumes</span>)</li><li>Habituer aux différents aliments <strong>avant <span class=\"kw-chiffre\">2 ans</span></strong> (légumes, fruits)</li><li>Faire <strong>goûter au moins une fois</strong> et représenter l'aliment sous des formes variées ; impliquer l'enfant dans la préparation</li></ul>"},"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/alimentation-besoins-nutritionnels-du-nourrisson-lenfant","label":"Collège Pédiatrie — Alimentation & besoins nutritionnels"},{"href":"https://radiopaedia.org/articles/rickets","label":"Radiopaedia : Rickets (rachitisme carentiel)"}],"cards":[{"i":"18e7ecb6512e","n":48,"o":"48-3","u":"Prise en charge","t":"Alimentation lactée exclusive : savoir comment","q":"Quels sont les principaux pièges à éviter concernant l'alimentation lactée du nourrisson et les apports hydriques ou énergétiques ?","a":"<p>Les pièges à éviter sont :</p><ul><li>Donner du <strong>lait de vache avant 1 an</strong>, ce qui est formellement proscrit.</li><li>Utiliser le <strong>micro-ondes pour chauffer le biberon</strong>, en raison du risque de brûlure.</li><li>Stocker les biberons préparés dans la porte du réfrigérateur : la <strong>température y est instable</strong>.</li><li>Penser que la stérilisation des biberons est toujours indispensable, elle ne l'est <strong>plus</strong>.</li></ul><p>Concernant les apports généraux :</p><ul><li>Le nourrisson est très sensible à la déshydratation en raison de l'immaturité rénale ; ses besoins hydriques sont d'environ <strong>150 mL/kg/j à la naissance</strong> et <strong>120 mL/kg/j avant 6 mois</strong>.</li><li>Les besoins énergétiques sont importants en période de croissance rapide, avec par exemple environ <strong>450 kcal/j à 1-3 mois</strong> et <strong>600 kcal/j à 4-6 mois</strong>.</li></ul>"},{"i":"6975741e002d","n":48,"o":"48-3","u":"Prise en charge","t":"Alimentation lactée exclusive : savoir comment","q":"Quelles sont les modalités de préparation et de conservation d'un biberon pour l'alimentation lactée exclusive du nourrisson ?","a":"<p>Pour la préparation d'un biberon :</p><ul><li>Utiliser <strong>1 cuillère-mesure pour 30 mL d'eau</strong> faiblement minéralisée ou de l'eau du robinet après l'avoir laissée couler plus de 5 minutes.</li><li>Verser l'<strong>eau en premier</strong> dans le biberon, puis la poudre de lait.</li><li>La <strong>stérilisation n'est pas indispensable</strong> ; un lavage au lave-vaisselle ou à la main est suffisant.</li></ul><p>Pour la conservation :</p><ul><li>Ne pas conserver les biberons préparés dans la porte du réfrigérateur en raison des variations de température.</li><li>Le biberon peut être donné à <strong>température ambiante</strong>. Si chauffé, il doit être consommé en <strong>moins de 30 minutes</strong>.</li><li><strong>Éviter le micro-ondes</strong> en raison du risque de brûlure.</li></ul>"},{"i":"b894d38cd260","n":48,"o":"48-3","u":"Prise en charge","t":"Alimentation lactée exclusive : savoir comment","q":"Quels sont les apports nutritionnels conseillés (quantités de lait et suppléments vitaminiques) pour un nourrisson en alimentation lactée exclusive ?","a":"<p>Les quantités de lait varient selon l'âge :</p><ul><li><strong>1<sup>ère</sup> semaine</strong> : de 6–7 x 10 mL à J1 à 6–7 x 70 mL à J7.</li><li><strong>2<sup>e</sup> semaine</strong> : 6 x 80 mL/jour.</li><li><strong>Jusqu'à 4 mois</strong> : augmentation progressive des quantités et diminution du nombre de biberons pour atteindre 4 x 180 mL/jour au 4<sup>e</sup> mois.</li></ul><p>Les supplémentations vitaminiques systématiques sont :</p><ul><li><strong>Vitamine K</strong> : <strong>2 mg PO à la naissance</strong>, <strong>2 mg PO entre J4-J7</strong>, puis <strong>2 mg PO à 1 mois</strong> en cas d'allaitement maternel exclusif (facultatif si préparation lactée).</li><li><strong>Vitamine D</strong> : <strong>400 à 800 UI/jour</strong> de 0 à 2 ans, que l'enfant soit allaité ou non.</li><li>Le fer est généralement couvert par les laits infantiles. Une supplémentation est systématique à partir du <strong>6<sup>e</sup> mois</strong> en cas d'allaitement maternel exclusif.</li><li>Le calcium n'est supplémenté que si la consommation est inférieure à 300 mg/jour.</li></ul>"},{"i":"2305faa66a50","n":48,"o":"48-4","u":"Prise en charge","t":"Diversification de l’alimentation : savoir comment","q":"Quels sont les interdits alimentaires spécifiques chez l'enfant de moins de 1 an ?","a":"<ul><li>Le <strong>miel</strong>, en raison du risque de botulisme infantile.</li><li>Le <strong>lait de vache</strong> (en tant que boisson principale).</li><li>Tous les interdits s'appliquant aux âges ultérieurs (< 3 ans et < 5 ans).</li></ul>"},{"i":"7a11f5936806","n":48,"o":"48-4","u":"Prise en charge","t":"Diversification de l’alimentation : savoir comment","q":"Quelles sont les recommandations concernant l'introduction des textures pendant la diversification alimentaire ?","a":"<ul><li>De <strong>4 à 8 mois</strong> : alimentation <strong>mixée/lisse</strong>.</li><li>De <strong>8 à 10 mois</strong> : alimentation <strong>moulinée</strong>.</li><li>À partir de <strong>10 mois</strong> : introduction de <strong>petits morceaux</strong> de tailles progressivement croissantes.</li></ul>"},{"i":"88820a418239","n":48,"o":"48-4","u":"Prise en charge","t":"Diversification de l’alimentation : savoir comment","q":"À quel âge doit-on débuter la diversification alimentaire chez l'enfant ?","a":"<p>La diversification alimentaire doit être débutée entre <strong>4 et 6 mois</strong>, jamais avant 4 mois.</p>"},{"i":"dd9f615a0264","n":48,"o":"48-4","u":"Prise en charge","t":"Diversification de l’alimentation : savoir comment","q":"Quel est le principe de la Diversification Menée par l'Enfant (DME) et quels sont les avantages et inconvénients ?","a":"<ul><li><strong>Principe</strong> : Proposer des aliments en morceaux au nourrisson dès qu'il peut tenir assis (vers <strong>6 mois</strong>). L'enfant se nourrit seul avec les doigts, l'allaitement ou les biberons de lait infantile étant poursuivis en parallèle.</li><li><strong>Avantage</strong> : Moins de troubles de l'oralité qu'avec la diversification à la cuillère.</li><li><strong>Inconvénients</strong> : Risques de <strong>fausses routes</strong> et risques de <strong>carences en lipides et fer</strong>. Son intérêt est limité et elle ne doit être proposée que si les conditions sont réunies.</li></ul>"},{"i":"e89d50020328","n":48,"o":"48-4","u":"Prise en charge","t":"Diversification de l’alimentation : savoir comment","q":"Quelles sont les recommandations concernant l'apport lacté pendant la diversification alimentaire jusqu'à 1 an, puis entre 1 et 3 ans ?","a":"<ul><li><strong>Jusqu'à 1 an</strong> : il faut conserver <strong><span style=\"text-decoration: underline;\">au moins</span> 3 <span style=\"text-decoration: underline;\">biberons/tétées par jour</span></strong>. Un apport de <strong>700 mL/jour</strong> de préparation de suite couvre la totalité des besoins en fer et en acides gras essentiels (AGE).</li><li><strong>Entre 1 et 3 ans</strong> : il est recommandé d'apporter <strong><span style=\"text-decoration: underline;\">au moins</span> 250 mL/jour</strong> de préparation lactée standard pour enfants en bas âge (<strong>lait de croissance</strong>), indispensable pour les apports en fer et AGE.</li></ul>"}]};